"""Core digest: hash a string, map the hash to a distinct-word phrase."""

from __future__ import annotations

import hashlib
import math
from importlib import resources


def _load_wordlist(name: str) -> tuple[str, ...]:
    text = resources.files(__package__).joinpath(f"wordlists/{name}.txt").read_text()
    return tuple(text.split())


#: Frozen word lists. Generated by ``scripts/build_wordlists.py`` from the
#: CC0 dariusk/corpora word lists, frequency-filtered so every word is one
#: an English speaker will recognize. The two lists are disjoint and each
#: is internally duplicate-free, so no phrase can ever repeat a word.
ADJECTIVES = _load_wordlist("adjectives")
NOUNS = _load_wordlist("nouns")

_MAX_ADJECTIVES = 8


def phrase_space(adjectives: int = 2) -> int:
    """Number of distinct phrases ``phrase_id`` can produce.

    With ``a`` adjectives drawn without repetition from a list of ``A`` and
    one noun from a list of ``N``, the space is ``A * (A-1) * ... * (A-a+1) * N``.
    """
    _check_adjective_count(adjectives)
    size = len(NOUNS)
    for i in range(adjectives):
        size *= len(ADJECTIVES) - i
    return size


def phrase_id(text: str | bytes, *, adjectives: int = 2, separator: str = "-") -> str:
    """Return a deterministic word-phrase digest of ``text``.

    The default is two adjectives and a noun (``brave-crimson-falcon``).
    ``adjectives`` may be raised to enlarge the phrase space (each extra
    adjective multiplies it by roughly the adjective-list size) or lowered
    to 1 for shorter, more collision-prone phrases.

    The mapping is uniform over the phrase space up to a bias below
    2**-170 (SHA-256 yields 256 uniform bits; the phrase space is under
    2**86 even at the maximum adjective count, and taking a 256-bit
    uniform value modulo M skews any outcome's probability by less than
    M / 2**256).
    """
    _check_adjective_count(adjectives)
    if isinstance(text, str):
        text = text.encode("utf-8")
    h = int.from_bytes(hashlib.sha256(text).digest(), "big")

    h, noun_index = divmod(h, len(NOUNS))

    # Draw adjectives without repetition: each draw indexes the pool of
    # not-yet-chosen words, then is mapped back to a position in the full
    # list by skipping over previously chosen positions.
    chosen: list[int] = []
    for i in range(adjectives):
        h, pick = divmod(h, len(ADJECTIVES) - i)
        for position in sorted(chosen):
            if pick >= position:
                pick += 1
        chosen.append(pick)

    words = [ADJECTIVES[i] for i in chosen] + [NOUNS[noun_index]]
    return separator.join(words)


def collision_probability(count: int, *, adjectives: int = 2) -> float:
    """Probability that ``count`` distinct inputs contain at least one
    pair mapping to the same phrase (the birthday bound).

    Uses ``1 - exp(-n(n-1) / 2M)``, which is accurate to well under the
    returned precision whenever ``count`` is small relative to the phrase
    space ``M`` — the only regime where the answer is interesting.
    """
    if count < 0:
        raise ValueError("count must be non-negative")
    space = phrase_space(adjectives)
    return -math.expm1(-count * (count - 1) / (2 * space))


def capacity(max_probability: float = 0.0001, *, adjectives: int = 2) -> int:
    """Largest number of distinct inputs whose total collision probability
    stays at or below ``max_probability`` (default 0.01%).
    """
    if not 0 < max_probability < 1:
        raise ValueError("max_probability must be between 0 and 1 exclusive")
    space = phrase_space(adjectives)
    # Invert the birthday approximation: n(n-1) = 2M * ln(1/(1-p)).
    target = -2 * space * math.log1p(-max_probability)
    count = int((1 + math.sqrt(1 + 4 * target)) / 2)
    while collision_probability(count, adjectives=adjectives) > max_probability:
        count -= 1
    return count


def _check_adjective_count(adjectives: int) -> None:
    if not 1 <= adjectives <= _MAX_ADJECTIVES:
        raise ValueError(f"adjectives must be between 1 and {_MAX_ADJECTIVES}")
